import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
F=[
("rule",[25],"المادة 11 (أ، ب)","يجوز للطالب المفصول من التخصص/الكلية (حسب كيفية قبوله) أن يتقدم بطلب قبول جديد إلى الجامعة باستثناء التخصص/الكلية المفصول منه، وفي حال قبوله قبولاً جديداً تطبق عليه أحكام المادتين (16) و(17).",
 "هل يجوز للطالب المفصول التقدم بطلب قبول جديد في الجامعة؟","ما شروط عودة الطالب المفصول بقبول جديد؟","انفصلت من تخصصي، بقدر أقدم قبول جديد؟"),
("rule",[25],"المادة 11 (ج)","إذا فُصل الطالب مرة أخرى من التخصص/الكلية الجديدة وفق أحكام المادة (10) يُفصل من الجامعة نهائياً ولا يجوز له العودة إليها.",
 "متى يُفصل الطالب من الجامعة نهائياً؟","ما أثر الفصل للمرة الثانية بعد القبول الجديد؟","إذا انفصلت مرة ثانية بعد قبول جديد شو بصير؟"),
("rule",[25],"المادة 11 (د)","تصدر جميع قرارات الفصل (من التخصص/الكلية أو من الجامعة) عن مجلس العمداء بناء على تنسيب من مجلس الكلية، وتشعر وحدة القبول والتسجيل الطالب إلكترونياً على آخر عنوان إلكتروني له لدى الجامعة.",
 "من يصدر قرارات الفصل وكيف يُبلَّغ بها الطالب؟","ما الجهة المخولة بإصدار قرار فصل الطالب؟","مين بصدر قرار الفصل وكيف بعرف فيه؟"),
("number",[26],"المادة 12 (أ)","يسمح للطالب بالانسحاب من مساقات سجل لها خلال الأسبوع الأول من بداية الفصل حسب التقويم الجامعي، ولا تثبت المساقات المنسحب منها في سجله الأكاديمي وترصد له الرسوم.",
 "متى يسمح بالانسحاب من المساق دون أن يثبت في السجل؟","ما أثر الانسحاب من مساق خلال الأسبوع الأول؟","إذا انسحبت من مادة بالأسبوع الأول بتثبت بسجلي؟"),
("number",[26],"المادة 12 (ب)","يسمح بالانسحاب من مساق خلال مدة أقصاها (13) أسبوعاً للمساقات العملية و(14) أسبوعاً للمساقات النظرية من بداية الفصل الأول أو الثاني، وخلال الأسابيع السبعة الأولى من الفصل الصيفي؛ ويثبت المساق في السجل بملاحظة (منسحب) ولا يدخل في ساعات النجاح والرسوب ومتطلبات التخرج ولا ترصد له الرسوم، ولا يجوز أن تقل ساعاته بعد الانسحاب عن الحد الأدنى للعبء الدراسي إلا بموافقة العميد.",
 "ما المدة القصوى للانسحاب من المساقات النظرية والعملية؟","ما حكم الانسحاب من مساق بعد الأسبوع الأول؟","لحد أي أسبوع بقدر أنسحب من مادة؟"),
("rule",[26],"المادة 12 (ج)","إذا اعتُبر الطالب منسحباً من جميع مساقاته في فصل ما بمقتضى المادة (7)، تكون دراسته لهذا الفصل «مؤجلة» ويحسب الفصل من مدة التأجيل المسموح بها، ويثبت ذلك في سجله الأكاديمي.",
 "ما أثر اعتبار الطالب منسحباً من جميع المساقات بسبب الغياب؟","كيف يُسجَّل الفصل إذا اعتُبر الطالب منسحباً من كل مساقاته؟","إذا انحسبت منسحب من كل المواد بسبب الغياب شو بصير بالفصل؟"),
("rule",[27],"المادة 13 (أ/1،2)","لا تؤجل الدراسة للطالب الجديد في الجامعة أو الطالب المنتقل إليها إلا بعد مضي فصل دراسي واحد على الأقل على دراسته، ولا تؤجل لطالب لديه مساقات نتيجتها غير مكتملة إلا بعد إكمالها، وإلا تُرصد له علامة الأعمال الفصلية فقط.",
 "متى يجوز للطالب الجديد تأجيل دراسته؟","هل يجوز للطالب الجديد التأجيل في فصله الأول؟","بقدر أأجل أول فصل إلي بالجامعة؟"),
("number",[27],"المادة 13 (أ/3)","إذا لم يسجل الطالب المنتظم لأي فصل دراسي ولم يتقدم بطلب تأجيل خلال (14) أسبوعاً من بداية الفصل الأول أو الثاني يؤجل له الفصل آلياً، على ألا تزيد مدة التأجيل عن أربعة فصول دراسية متقطعة أو متصلة وألا يكون تخصصه من التخصصات المجمد القبول فيها، ويجوز أن تصل إلى ستة فصول كحد أعلى بقرار من مجلس الكلية، وإذا تجاوزها فقد مقعده في الجامعة.",
 "كم فصلاً يجوز تأجيل الدراسة وماذا يحدث عند تجاوز المدة؟","ما الحد الأقصى لمدة تأجيل الدراسة؟","كم فصل بقدر أأجل قبل ما أخسر مقعدي؟"),
("rule",[27],"المادة 13 (أ/4،5)","لا تحسب مدة التأجيل من الحد الأعلى لمدة الدراسة أو لغايات إزالة أسباب الوضع تحت المراقبة، ولا يحسب الفصل الذي يفصل منه الطالب بعقوبة تأديبية من الحد الأعلى لمدة الدراسة أو التأجيل.",
 "هل تحسب مدة التأجيل من الحد الأعلى لمدة الدراسة؟","ما أثر فصل الطالب بعقوبة تأديبية على الحد الأعلى لمدة الدراسة؟","مدة التأجيل بتحسب من الحد الأعلى لسنوات الدراسة؟"),
("rule",[27,28],"المادة 13 (ب)","يفقد الطالب مقعده إذا تجاوز مدة التأجيل المسموح بها، ويجوز له التقدم بطلب جديد: فإذا قُبل في التخصص والخطة نفسها الفعالة يحتفظ بسجله الأكاديمي كاملاً وتحسب مدة دراسته السابقة ضمن الحد الأعلى، وإذا قُبل في خطة مختلفة أو غير فعالة أو في تخصص آخر تطبق عليه المادة (16).",
 "ماذا يحدث إذا فقد الطالب مقعده ثم قُبل من جديد؟","هل يحتفظ الطالب الفاقد لمقعده بسجله الأكاديمي عند إعادة قبوله؟","فقدت مقعدي وقبلوني من جديد، بضل سجلي؟"),
("number",[28],"المادة 13 (ب/3)","لا يجوز احتساب السجل الأكاديمي للطالب لأغراض مواصلة الدراسة إذا انقطع عن الدراسة أربع سنوات فأكثر.",
 "بعد كم سنة انقطاع لا يُحتسب السجل الأكاديمي للطالب؟","ما مدة الانقطاع التي تُسقط السجل الأكاديمي؟","إذا انقطعت عن الدراسة كم سنة بينحذف سجلي؟"),
("procedure",[28],"المادة 13 (ج)","يتقدم الطالب بطلب انسحاب إلكتروني من الجامعة، فتثبت حالة «منسحب من الجامعة» في سجله ويكون قد فقد مقعده فيها، وإذا رغب بالالتحاق بها مرة أخرى تطبق عليه أحكام الفقرة (ب/2) من المادة نفسها.",
 "كيف ينسحب الطالب من الجامعة وما أثر ذلك على مقعده؟","ما إجراء الانسحاب من الجامعة؟","كيف بنسحب من الجامعة كلها وبضل مقعدي؟"),
("rule",[29],"المادة 14","يشترط لانتقال الطالب من جامعة أردنية رسمية إلى جامعة العلوم والتكنولوجيا أن يكون مقبولاً ضمن قوائم وحدة تنسيق القبول الموحد في وزارة التعليم العالي، وأن تنطبق عليه إحدى الحالات: الإصابة بالسرطان (قيد العلاج الكيماوي أو الإشعاعي)، أو الفشل الكلوي المزمن الذي يستدعي غسيلاً منتظماً، أو أمراض الدماغ والأعصاب المسببة لشلل جزئي أو كلي يعيق الحركة ولا يرجى شفاؤه (بتقارير طبية معتمدة وموافقة اللجنة الطبية العليا ومجلس العمداء)، أو القضايا العشائرية التي تستدعي الجلوة.",
 "ما شروط الانتقال من جامعة أردنية رسمية إلى جامعة العلوم والتكنولوجيا؟","في أي حالات يُسمح بالانتقال من جامعة رسمية أخرى إلى الجامعة؟","بدي أنتقل من جامعة حكومية لجامعة العلوم والتكنولوجيا، شو الشروط؟"),
("rule",[29],"المادة 14 (ثانياً/2)","في القضايا العشائرية التي تستدعي الجلوة يكون الانتقال مؤقتاً لمدة فصل دراسي واحد قابل للتجديد، ويقدم الطالب كتاباً من الحاكم الإداري في اللواء؛ وإذا استمرت القضية واجتاز الطالب أكثر من 50% من الخطة الدراسية في جامعة العلوم والتكنولوجيا أو وصل فصل التخرج فيمكن منحه الدرجة منها.",
 "كيف يتم الانتقال في حالة القضايا العشائرية؟","ما مدة الانتقال المؤقت في القضايا العشائرية وكيف يحصل الطالب على الدرجة؟","كيف بنتقل الطالب اللي عنده قضية عشائرية؟"),
("rule",[30],"المادة 15","تتم إجراءات تغيير التخصص للطلبة وفق أسس تغيير التخصص المقرة والمعمول بها في الجامعة.",
 "وفق أي أسس تتم إجراءات تغيير التخصص؟","ما المرجع الذي يحكم تغيير التخصص؟","كيف بيتم تغيير التخصص؟"),
("procedure",[31],"المادة 16 (1)","إذا قُبل الطالب في تخصص جديد وكان قد درس مساقات في تخصص آخر داخل الجامعة، فعليه إجراء احتساب المساقات عبر بوابة خدمات الطالب الإلكترونية قبل تسجيل المساقات في فصل القبول، على أن تُستكمل إجراءات المعادلة خلال السنة الأولى كحد أقصى، ويختار: (أ) احتساب جميع المساقات الناجح بها مع إدخال نقاطها في المعدل التراكمي ويحسم فصل دراسي من الحد الأعلى لمدة الدراسة مقابل كل (15) ساعة معتمدة تحتسب له، أو (ب) المعاملة كطالب مستجد دون احتساب أي مساق.",
 "كيف تُحتسب المساقات التي درسها الطالب في تخصص آخر عند تغيير التخصص أو قبوله في تخصص جديد؟","ما خيارا الطالب في احتساب مساقاته السابقة داخل الجامعة؟","غيرت تخصصي، كيف بتنحسب موادي القديمة؟"),
("number",[31],"المادة 16 (1/أ)","يُحسم فصل دراسي واحد من الحد الأعلى لمدة الدراسة مقابل كل (15) ساعة معتمدة تحتسب للطالب من مساقات تخصصه السابق داخل الجامعة.",
 "كم ساعة تُحسم مقابلها فصل من الحد الأعلى لمدة الدراسة عند احتساب مساقات التخصص السابق؟","ما أثر احتساب الساعات من التخصص السابق على الحد الأعلى للدراسة؟","كم ساعة بتحسبلي فصل من مدة الدراسة بعد تغيير التخصص؟"),
("procedure",[32],"المادة 17 (أ)","يتقدم الطالب بطلب معادلة المساقات التي درسها خارج الجامعة خلال أسبوعين من بدء الفصل الأول لقبوله إلكترونياً و/أو ورقياً، وتدرس لجنة معادلة المساقات في الكلية الطلبات ويبت بها العميد خلال أسبوعين من تقديمها، على أن تستكمل إجراءات المعادلة خلال السنة الأولى كحد أقصى.",
 "متى وكيف يقدم الطالب طلب معادلة مساقات درسها خارج الجامعة؟","ما المدة المتاحة لتقديم طلب المعادلة والبت فيه؟","بدي أعادل مواد من جامعة ثانية، كيف وخلال قديش؟"),
("rule",[32],"المادة 17 (أ)","تُعادَل المساقات من خارج الجامعة إذا: (1) كان عدد ساعات المساق الخارجي يساوي أو يزيد على ساعات المساق الداخلي (ويمكن دمج مساقين أو أكثر)، و(2) تكافأ المساقان في مخرجات التعلم بنسبة لا تقل عن 80% بتقدير لجنة المعادلة، و(3) نجح الطالب في المساق في مؤسسته التعليمية.",
 "ما شروط معادلة مساق من خارج الجامعة؟","ما نسبة التكافؤ المطلوبة في مخرجات التعلم لمعادلة المساقات؟","شو شروط معادلة مادة من جامعة ثانية؟"),
("rule",[33],"المادة 17 (ب)","لدراسة مساق في جامعة أخرى خلال الصيف يجب الحصول على موافقة مسبقة من عميد الكلية بالتنسيق مع عميد الكلية التي تطرح المساق، بشرط: عدم طرح المساق في الصيفي أو وجود تعارض لا يمكن حله، وتكافؤ مخرجات التعلم بنسبة لا تقل عن 80%، وتساوي عدد الساعات أو زيادتها، وألا يتجاوز المجموع داخل الجامعة وخارجها العبء المسموح به، والنجاح في المساق، وعدم دراسة المساق أو مكافئه سابقاً في الجامعة أو الرسوب به.",
 "ما شروط دراسة مساق في جامعة أخرى خلال الفصل الصيفي؟","هل يمكن دراسة مساقات الصيفي في جامعة أخرى وما الشروط؟","بدي أدرس مادة بجامعة ثانية بالصيف، شو لازم؟"),
("number",[33],"المادة 17 (د)","لا يجوز أن يتجاوز مجموع الساعات المحتسبة للطالب من خارج الجامعة (باستثناء طلبة التجسير): (60) ساعة معتمدة للتخصصات التي متوسط دراستها 4 سنوات، و(75) ساعة لتخصصات الـ5 سنوات، و(98) ساعة لتخصصات الـ6 سنوات.",
 "ما الحد الأعلى للساعات التي تُحتسب للطالب من خارج الجامعة؟","كم ساعة كحد أقصى يمكن معادلتها من خارج الجامعة حسب مدة التخصص؟","كم ساعة بقدر أعادل من برا الجامعة؟"),
("rule",[34],"المادة 17 (هـ، و، ز)","تثبت للمساقات المعادلة التي درسها الطالب خارج الجامعة نتيجة «معفى» ولا تدخل في معدله التراكمي، ويُحسم فصل دراسي من الحد الأعلى لمدة الدراسة مقابل كل (15) ساعة تحسب له، ولا تحتسب ساعات الطلبة الذين يدرسون في جامعة أخرى خلال فترة تأجيل دراستهم أو انسحابهم أو فقدانهم لمقاعدهم.",
 "هل تدخل المساقات المعادلة من خارج الجامعة في المعدل التراكمي؟","ما أثر المساقات المعادلة على المعدل والحد الأعلى لمدة الدراسة؟","المواد المعادلة من برا الجامعة بتدخل بمعدلي؟"),
("rule",[35],"المادة 18 (أ)","يكون المساق مكافئاً لمساق آخر إذا ورد ذلك في الخطة الدراسية أو الخطة الانتقالية، أو كان محتواه مطابقاً لمحتوى مساق في كلية أخرى.",
 "متى يعتبر المساق مكافئاً لمساق آخر؟","ما المقصود بالمساق المكافئ؟","شو يعني المساق المكافئ؟"),
("rule",[35],"المادة 18 (ب-هـ)","يجوز تسجيل المساق المكافئ بدلاً من الأصيل بموافقة عميد كلية الطالب بالتنسيق مع عميد الكلية التي تطرحه، إذا كان الأصيل غير مطروح في ذلك الفصل أو وُجد تعارض لا يمكن حله في جدول الطالب؛ ويجب أن يساوي المكافئ الأصيل في عدد الساعات (أو يزيد)، ويكون لجميع الطلبة في التخصص أو الحالات المشابهة.",
 "متى يجوز تسجيل المساق المكافئ بدلاً من الأصيل؟","ما شروط تسجيل المساق المكافئ؟","بقدر أسجل المادة المكافئة بدل الأصلية؟ ومتى؟"),
("rule",[36],"المادة 19 (أ)","إذا توقف احتمال تخرج الطالب على مساق إجباري أو اختياري واحد ولم يتمكن من تسجيله لعدم طرحه أو طرح مكافئه أو لتعارض لا يمكن حله أو لأسباب اضطرارية، فلعميد الكلية بتنسيب من رئيس القسم استبداله بمساق (أو أكثر) ذي علاقة بتخصصه في المستوى نفسه أو أعلى وبالساعات نفسها أو أكثر، ويعلم المسجل العام قبل نهاية فترة الانسحاب والإضافة.",
 "متى يجوز استبدال مساق بمساق بديل لطالب يتوقف تخرجه عليه؟","ما شروط المساق البديل ومن يقرره؟","المادة اللي بدي أتخرج فيها مش مطروحة، بقدر آخد بديل؟"),
("rule",[36],"المادة 19 (ب، ج)","لمجلس الكلية الموافقة لأسباب اضطرارية على دراسة الطالب مساقاً بديلاً ثانياً في الفصل نفسه، ويحق للطالب زيادة العبء عن (18) ساعة بحد أقصى (21) ساعة، وفي الصيفي (10) ساعات بحد أقصى (13)؛ ويجوز للمتوقع تخرجه في الصيفي تسجيل مساقين بديلين، ولمن ينهي ساعاته في الصيفي ويبقى عليه التدريب مساق بديل واحد.",
 "كم مساقاً بديلاً يجوز للطالب المتوقع تخرجه تسجيله في الفصل الصيفي؟","هل يجوز تسجيل مساقين بديلين في فصل واحد؟","بقدر آخد مادتين بديلتين بنفس الفصل؟"),
("rule",[36,37],"المادة 19 (د)","تدخل نقاط المساق الأصيل في حساب المعدل التراكمي عند دراسة مساق بديل عنه؛ وإذا رسب الطالب في المساق البديل تبقى نقاطه ضمن المعدل التراكمي وتخرج في حال درس الأصيل أو مكافئاً له؛ وإذا لم يتخرج بسبب رسوبه في مساق آخر أو لمعدل تراكمي أقل من (2.00) يبقى حساب نقاط البديل ضمن معدله ولا يطلب منه إعادة المساق الأصيل.",
 "كيف تُحتسب نقاط المساق البديل في المعدل التراكمي؟","ما أثر الرسوب في المساق البديل على المعدل؟","إذا رسبت بالمادة البديلة شو بصير بمعدلي؟"),
("rule",[37],"المادة 19 (هـ، و)","لعمداء الكليات السماح للطالب المتوقع تخرجه بتسجيل مساق بديل عن مساق رسب به ثلاث مرات فأكثر (من مساقات السنة الأولى أو المتطلبات الإجبارية للكليات أو الأقسام)، ولا يجوز أن يكون المساق البديل من متطلبات الجامعة الاختيارية أو الإجبارية مهما كانت الأسباب.",
 "هل يجوز تسجيل بديل عن مساق رسب به الطالب ثلاث مرات؟","هل يمكن أن يكون المساق البديل من متطلبات الجامعة؟","رسبت بمادة تلات مرات، بقدر آخد بديل؟"),
("list",[38],"المادة 20","تمنح درجة البكالوريوس بعد إتمام المتطلبات الآتية: (أ) النجاح في جميع المساقات المطلوبة حسب الخطة الدراسية المعتمدة، (ب) معدل تراكمي لا يقل عن (2.00)، (ج) عدم تجاوز الحد الأعلى لمدة الدراسة، (د) أن يكون الطالب منتظماً مسجلاً في آخر فصل دراسي له في الجامعة وقد أتم ما لا يقل عن نصف الساعات المعتمدة لتخصصه في الجامعة.",
 "ما متطلبات التخرج ومنح درجة البكالوريوس؟","ما الشروط التي يجب توافرها ليحصل الطالب على درجة البكالوريوس؟","شو لازم أحقق عشان أتخرج؟"),
("number",[38],"المادة 20 (ب)","الحد الأدنى للمعدل التراكمي المطلوب للتخرج هو (2.00).",
 "ما أقل معدل تراكمي مطلوب للتخرج؟","كم الحد الأدنى للمعدل التراكمي للحصول على درجة البكالوريوس؟","شو أقل معدل تراكمي لازم أجيبه عشان أتخرج؟"),
("rule",[38],"المادة 20 (د)","يشترط في آخر فصل للطالب أن يكون طالباً منتظماً، وأن يكون قد أتم دراسة ما لا يقل عن نصف عدد الساعات المعتمدة لتخصصه في الجامعة.",
 "كم ساعة يجب أن يدرسها الطالب في الجامعة على الأقل ليتخرج منها؟","ما النسبة الدنيا من الساعات التي يجب دراستها في الجامعة للتخرج؟","كم ساعة لازم أدرسها بالجامعة نفسها عشان أتخرج منها؟"),
("rule",[39],"المادة 21","يجوز للطالب وبموافقة عميد كليته تأجيل تخرجه لفصل دراسي واحد فقط (بما فيه الصيفي) لأغراض رفع معدله التراكمي، مع مراعاة أحكام الإعادة والحد الأعلى لفصول الدراسة، وذلك قبل صدور قرار مجلس العمداء بتخريجه.",
 "هل يجوز تأجيل التخرج لرفع المعدل؟","كم فصلاً يمكن تأجيل التخرج لتحسين المعدل ومن يوافق؟","بقدر أأجل تخرجي عشان أرفع معدلي؟"),
("rule",[40],"المادة 22","على الطالب أن يحصل على براءة ذمة من الجامعة لاستكمال إجراءات تخرجه.",
 "ما الوثيقة المطلوبة لاستكمال إجراءات التخرج؟","هل يحتاج الطالب إلى براءة ذمة للتخرج؟","شو بحتاج لأخلص إجراءات تخرجي؟"),
("rule",[41,42],"المادة 23 و24","تمنح شهادات التخرج عند استحقاقها في كل فصل دراسي، وتصدر وثائق التخريج (شهادة جدارية، مصدقة، كشف علامات) للخريجين العرب بالعربية ولغير العرب بالإنجليزية؛ وتقام حفلة التخريج مرتين في العام (بعد الفصل الأول وبعد الفصل الثاني)، وتحمل الدرجة تاريخ استحقاقها، ويسمح للمتوقع تخرجهم في نهاية الصيفي (بما فيه التدريب) بحضور حفل التخريج.",
 "كم مرة تقام حفلة التخريج في العام الجامعي؟ ومتى يحضرها طلبة الصيفي؟","بأي لغة تصدر وثائق التخريج وكم مرة يقام الحفل؟","كم مرة بيعملوا حفل تخريج بالسنة؟"),
("rule",[43],"المادة 25","رئيس القسم المختص والمرشد الأكاديمي مسؤولان عن متابعة السير الأكاديمي للطالب والتحقق من استيفائه شروط التخرج، وعلى المرشد إبلاغه بذلك دورياً.",
 "من المسؤول عن متابعة السير الأكاديمي للطالب والتحقق من شروط التخرج؟","ما دور المرشد الأكاديمي في متابعة شروط التخرج؟","مين بتابع إني مستوفي شروط التخرج؟"),
("rule",[44],"المادة 26","لا يجوز لأي طالب أن يعترض بحجة عدم علمه بهذه التعليمات أو عدم اطلاعه على النشرات الصادرة عن الجامعة أو المنشورة على لوحة إعلاناتها أو موقعها أو المرسلة إلى بريده الإلكتروني.",
 "هل يُقبل اعتراض الطالب بأنه لم يعلم بالتعليمات؟","هل يعفى الطالب من تطبيق التعليمات لعدم اطلاعه عليها؟","بقدر أحكي ما كنت أعرف بالتعليمات؟"),
("rule",[45,46],"المادة 27 و28","يبت مجلس العمداء في الحالات التي لم يرد فيها نص في التعليمات وفي الإشكالات التي تنشأ عن تطبيقها، ورئيس الجامعة والمسجل العام وعمداء الكليات ورؤساء الأقسام ومدرسو المساقات مكلفون بتنفيذها كلٌّ حسب اختصاصه.",
 "من يبت في الحالات التي لم يرد فيها نص في تعليمات منح درجة البكالوريوس؟","من يقرر في الحالات غير المنصوص عليها في التعليمات؟","إذا في حالة مش مكتوبة بالتعليمات مين بقرر؟"),
]
save('0214','تعليمات منح درجة البكالوريوس رقم (1) لسنة 1987 (المعدلة)',F,'c')
